INSERT INTO feature VALUES('loop-carried-state','effects','Loop-carried state through held slots','loops','implemented','notable',NULL,'A slot held outside a loop and accessed inside it is threaded as an accumulator argument of the loop''s tail-recursive fold, so a loop mutates only the state its recursive call shows and the measure reads the accumulator; a nested loop over the same slot is refused by name until it is threaded in turn. An endpoint bound outside a `loop` or a `while` and named inside it is threaded the same way, placed again in each pass: the first pass takes it at the state the loop starts in, and a pass hands it on only at that state.','surface-lowering core-checker','corpus/model/control/accessor-loop.gandr corpus/pathological/control/accessor-loop-nested.gandr corpus/model/sessions/endpoint-loop.gandr corpus/pathological/sessions/endpoint-loop.gandr','corpus/model/control/accessor-loop.gandr','#1143 #4502');
